function num(value: unknown) { return new Intl.NumberFormat("ru-RU").format(Number(value) || 0); }
function money(value: unknown) { return value == null ? "—" : new Intl.NumberFormat("ru-RU", { style: "currency", currency: "RUB", maximumFractionDigits: 0 }).format(Number(value) || 0); }
function date(value: unknown, full = false) { if (!value) return "—"; const d = new Date(String(value)); return Number.isNaN(d.getTime()) ? String(value) : d.toLocaleString("ru-RU", full ? { dateStyle: "short", timeStyle: "short" } : { dateStyle: "medium" }); }
function percent(value: unknown) { return `${new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 1 }).format(Number(value) || 0)}%`; }
function arr(value: unknown): Data[] { return Array.isArray(value) ? value : []; }
function getMetric(data: Data, ...keys: string[]) { for (const key of keys) { if (data?.[key] != null) return data[key]; if (data?.metrics?.[key] != null) return data.metrics[key]; } return 0; }
function dateRange(period: string, timezone: string) {
  let today: string;
  try { today = new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date()); }
  catch { today = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Moscow", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date()); }
  const before = (days: number) => new Date(new Date(`${today}T12:00:00Z`).getTime() - days * 86400000).toISOString().slice(0, 10);
  return period === "yesterday" ? { from: before(1), to: before(1) } : { from: period === "today" ? today : before(Number(period) - 1), to: today };
}

function Field({ label, hint, children, wide = false }: { label: string; hint?: string; children: ReactNode; wide?: boolean }) {
  return <label className={`adm-field${wide ? " adm-field-wide" : ""}`}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>;
}
function Empty({ title = "Пока нет данных", text = "Данные появятся после первых переходов по вашим рекламным ссылкам.", children }: { title?: string; text?: string; children?: ReactNode }) {
  return <div className="adm-empty"><span className="adm-empty-icon"><Icon name="chart" size={27}/></span><h3>{title}</h3><p>{text}</p>{children}</div>;
}
function Modal({ title, children, close, wide = false }: { title: string; children: ReactNode; close: () => void; wide?: boolean }) {
  const dialog = useRef<HTMLElement>(null);
  useEffect(() => {
    const previousFocus = document.activeElement as HTMLElement | null;
    dialog.current?.querySelector<HTMLElement>("input, select, textarea, button")?.focus();
    const fn = (e: KeyboardEvent) => {
      if (e.key === "Escape") close();
      if (e.key !== "Tab") return;
      const focusable = [...(dialog.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select, textarea, a[href], iframe') ?? [])];
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }
    };
    document.addEventListener("keydown", fn); const before = document.body.style.overflow; document.body.style.overflow = "hidden";
    return () => { document.removeEventListener("keydown", fn); document.body.style.overflow = before; previousFocus?.focus(); };
  }, []);
  return <div className="adm-overlay" onMouseDown={e => { if (e.target === e.currentTarget) close(); }}><section ref={dialog} className={`adm-modal${wide ? " adm-modal-wide" : ""}`} role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button className="adm-icon-button" type="button" onClick={close} aria-label="Закрыть"><Icon name="close"/></button></header>{children}</section></div>;
}

function Chart({ rows, primary = "visits", secondary = "clicks", title = "Динамика посещений", subtitle = "Посещения и целевые переходы за период" }: { rows: Data[]; primary?: string; secondary?: string; title?: string; subtitle?: string }) {
  const get = (r: Data, key: string) => Number(r[key] ?? (key === "visits" ? r.landingViews ?? r.landing : key === "clicks" ? r.socialClicks ?? r.outboundClicks : 0)) || 0;
  const max = Math.max(1, ...rows.flatMap(r => [get(r, primary), get(r, secondary)]));
  const points = (key: string) => rows.map((r, i) => `${32 + i * 596 / Math.max(1, rows.length - 1)},${174 - get(r, key) / max * 142}`).join(" ");
  return <section className="adm-card adm-chart-card"><div className="adm-card-heading"><div><h2>{title}</h2><p>{subtitle}</p></div><span className="adm-chart-legend"><i/>Посещения <i/>Клики</span></div>{rows.length ? <><svg viewBox="0 0 660 211" className="adm-chart" role="img" aria-label={title}><defs><linearGradient id="adm-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8bd856" stopOpacity=".26"/><stop offset="100%" stopColor="#8bd856" stopOpacity="0"/></linearGradient></defs>{[0, 1, 2, 3].map(v => <g key={v}><line x1="32" x2="628" y1={32 + v * 47.33} y2={32 + v * 47.33} stroke="#ebeee7" strokeDasharray="4 4"/><text x="2" y={36 + v * 47.33} fill="#959c91" fontSize="10">{num(max * (1 - v / 3))}</text></g>)}<polygon points={`32,174 ${points(primary)} 628,174`} fill="url(#adm-area)"/><polyline points={points(primary)} stroke="#70b642" strokeWidth="2.5" fill="none" strokeLinejoin="round"/><polyline points={points(secondary)} stroke="#7a8fa6" strokeWidth="2" fill="none" strokeLinejoin="round"/>{rows.filter((_, i) => i === 0 || i === rows.length - 1 || i % Math.max(1, Math.ceil(rows.length / 5)) === 0).map((r, i, filtered) => <text key={i} x={32 + rows.indexOf(r) * 596 / Math.max(1, rows.length - 1)} y="204" textAnchor={i === 0 ? "start" : i === filtered.length - 1 ? "end" : "middle"} fontSize="10" fill="#8b9386">{date(r.date ?? r.day)}</text>)}</svg></> : <Empty title="Первые переходы — начало графика" text="Здесь будет динамика реальных посещений и кликов. Демонстрационные значения не используются."/>}</section>;
}

function ContentEditor({ value, onChange, path = "" }: { value: any; onChange: (value: any) => void; path?: string }) {
  if (path === "" && value && typeof value === "object") return <div className="adm-form-grid">{CONTENT_GROUPS.map(group => <fieldset className="adm-content-group" key={group.title}><legend>{group.title}</legend><ContentEditor value={Object.fromEntries(group.fields.map(key => [key, value[key]]))} path="group" onChange={patch => onChange({ ...value, ...patch })}/></fieldset>)}</div>;
  if (typeof value === "boolean") return <label className="adm-check"><input type="checkbox" checked={value} onChange={e => onChange(e.target.checked)}/>{LABELS[path.split(".").pop() || ""] || "Показывать"}</label>;
  if (Array.isArray(value)) return <div className="adm-content-array">{value.map((item, i) => <div className="adm-content-item" key={i}><div className="adm-content-item-title"><span>Пункт {i + 1}</span><button type="button" className="adm-text-button" disabled={path === "steps" && value.length <= 1} onClick={() => onChange(value.filter((_, j) => j !== i))}>Удалить</button></div><ContentEditor value={item} path={`${path}.${i}`} onChange={next => onChange(value.map((old, j) => j === i ? next : old))}/></div>)}<button type="button" className="adm-button adm-button-small" disabled={(path === "steps" && value.length >= 10) || (path === "incomeExamples" && value.length >= 20)} onClick={() => onChange([...value, value.length ? structuredClone(value[value.length - 1]) : path === "incomeExamples" ? { title: "Название примера", calculation: "Укажите проверенный расчёт вознаграждения" } : path === "steps" ? { title: "Название шага", text: "Описание" } : "Новый пункт"])}><Icon name="plus" size={15}/>Добавить пункт</button></div>;
  if (value && typeof value === "object") return <div className="adm-form-grid">{Object.entries(value).filter(([key]) => key !== "metrikaId").map(([key, item]) => typeof item === "object" && item !== null ? <fieldset className="adm-content-group" key={key}><legend>{LABELS[key] || key}</legend><ContentEditor value={item} path={path ? `${path}.${key}` : key} onChange={next => onChange({ ...value, [key]: next })}/></fieldset> : <Field key={key} label={LABELS[key] || key} hint={key === "intro" ? "Каждый пункт — с новой строки. Текст до первого двоеточия выделяется жирным." : undefined} wide={typeof item === "string" && (item.length > 85 || /text|description|body|privacy|legal|disclaimer|subtitle|intro/i.test(key))}>{typeof item === "boolean" ? <input type="checkbox" checked={item} onChange={e => onChange({ ...value, [key]: e.target.checked })}/> : typeof item === "number" ? <input type="number" value={item} onChange={e => onChange({ ...value, [key]: Number(e.target.value) })}/> : (String(item ?? "").length > 85 || /text|description|body|privacy|legal|disclaimer|subtitle|intro/i.test(key)) ? <textarea rows={key === "intro" ? 6 : /privacy|legal/i.test(key) ? 7 : 3} value={String(item ?? "")} onChange={e => onChange({ ...value, [key]: e.target.value })}/> : <input value={String(item ?? "")} onChange={e => onChange({ ...value, [key]: e.target.value })}/>}</Field>)}</div>;
  return <textarea rows={3} value={String(value ?? "")} onChange={e => onChange(e.target.value)}/>;
}

