export function AdminApp({ section = "dashboard", user, csrf }: { section?: string; user: { email: string }; csrf: string }) {
  const [current, setCurrent] = useState<Section>(NAV.some(x => x.id === section) ? section as Section : "dashboard");
  const [menu, setMenu] = useState(false);
  const [data, setData] = useState<Data | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState<Notice>(null);
  const [period, setPeriod] = useState("30");
  const [filters, setFilters] = useState<Data>({ dataMode: "live", quality: "clean", timezone: "Europe/Moscow" });
  const [sourceForm, setSourceForm] = useState<Data | null>(null);
  const [campaignForm, setCampaignForm] = useState<Data | null>(null);
  const [deleteRequest, setDeleteRequest] = useState<{ section: "campaigns" | "sources"; record: Data } | null>(null);
  const [deleteConfirmation, setDeleteConfirmation] = useState("");
  const [sourceDetail, setSourceDetail] = useState<Data | null>(null);
  const [selected, setSelected] = useState<string[]>([]);
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("name");
  const [linkScope, setLinkScope] = useState("");
  const [links, setLinks] = useState<Data>({ vk: "", telegram: "", max: "" });
  const [linkModes, setLinkModes] = useState<Data>({ vk: "plain", telegram: "plain", max: "plain" });
  const [draft, setDraft] = useState<Data | null>(null);
  const [preview, setPreview] = useState(false);
  const [settingsForm, setSettingsForm] = useState<Data | null>(null);
  const [conversion, setConversion] = useState<Data>({ sourceId: "", type: "lead", count: 1, occurredAt: "", externalId: "", notes: "", isTest: false });
  const [csv, setCsv] = useState("");
  const [qrSize, setQrSize] = useState("1024");
  const [refreshIndex, setRefreshIndex] = useState(0);
  const [refreshing, setRefreshing] = useState(false);
  const refreshStartedAt = useRef(0);
  const refreshBusy = loading || refreshing;

  function refreshData() {
    if (refreshBusy) return;
    refreshStartedAt.current = Date.now();
    setRefreshing(true);
    setLoading(true);
    setRefreshIndex(index => index + 1);
  }

  useEffect(() => {
    if (!refreshing || loading) return;
    // Keep a quick response visibly acknowledged; data itself is displayed immediately.
    const timer = setTimeout(() => setRefreshing(false), Math.max(0, 800 - (Date.now() - refreshStartedAt.current)));
    return () => clearTimeout(timer);
  }, [refreshing, loading]);

  const query = useMemo(() => {
    const params = new URLSearchParams();
    Object.entries(filters).forEach(([key, value]) => { if (value !== "" && value != null) params.set(key, String(value)); });
    if (period !== "custom") { const range = dateRange(period, filters.timezone || "Europe/Moscow"); params.set("from", range.from); params.set("to", range.to); }
    return params.toString();
  }, [filters, period, refreshIndex]);
  const [requestQuery, setRequestQuery] = useState(query);
  useEffect(() => { const timer = setTimeout(() => setRequestQuery(query), 250); return () => clearTimeout(timer); }, [query]);

  useEffect(() => {
    let active = true; const controller = new AbortController(); setLoading(true);
    fetch(`/api/admin/bootstrap?${requestQuery}`, { signal: controller.signal, cache: "no-store" }).then(async response => { const result = await response.json(); if (!response.ok) throw new Error(result.error || "Не удалось загрузить данные"); return result; }).then(result => { if (!active) return; setData(result); setDraft(old => old ? { ...old, metrikaId: result.settings?.metrikaId ?? old.metrikaId } : result.settings?.draft ?? result.settings?.draftContent ?? result.settings?.contentDraft ?? result.settings?.content ?? result.content ?? null); setSettingsForm(old => old ?? result.settings ?? {}); }).catch(error => { if (active && error.name !== "AbortError") setNotice({ kind: "error", text: error.message }); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; controller.abort(); };
  }, [requestQuery, refreshIndex]);

  const campaigns = arr(data?.campaigns);
  const sourceCampaign = campaigns.find(c => c.id === sourceForm?.campaignId);
  const inheritedCategory = sourceCampaign?.category;
  const sources = arr(data?.sources);
  const report = data?.report ?? {};
  const summary = report.metrics ?? report.summary ?? report.totals ?? report;
  const reportSources = [...arr(report.sources ?? report.bySource).map(r => ({ ...r, ...(r.metrics ?? {}) })), ...(report.unattributed ? [{ ...report.unattributed, id: "unattributed", name: "Без источника · direct / unknown" }] : [])];
  const reportCampaigns = arr(report.campaigns ?? report.byCampaign).map(r => ({ ...r, ...(r.metrics ?? {}) }));
  const daily = arr(report.daily ?? report.byDay ?? report.timeline);
  const audit = arr(data?.audit);
  const history = arr(data?.linkHistory);
  const confirmedResults = arr(data?.confirmedResults);
  const settings = data?.settings ?? {};
  const activeNav = NAV.find(x => x.id === current)!;
  const visited = Number(getMetric(summary, "landingViews", "visits", "landingVisits"));
  const sessions = Number(getMetric(summary, "uniqueSessions", "sessions"));
  const clicks = Number(getMetric(summary, "socialClicks", "clicks", "outboundClicks"));
  const conversionRate = getMetric(summary, "conversionRate", "conversion");
  const filteredSources = useMemo(() => sources.filter(s => (!filters.campaignId || s.campaignId === filters.campaignId) && (!filters.sourceId || s.id === filters.sourceId) && (!filters.platform || s.platform === filters.platform) && (!filters.partner || String(s.partner).toLowerCase().includes(String(filters.partner).toLowerCase())) && (!filters.category || s.category === filters.category) && (!filters.creative || s.creative === filters.creative) && (filters.dataMode === "all" || Boolean(s.isTest) === (filters.dataMode === "test")) && (!search || [s.name, s.code, s.partner, s.city, s.platform].join(" ").toLowerCase().includes(search.toLowerCase()))).sort((a, b) => sort === "cost" ? Number(b.cost) - Number(a.cost) : sort === "created" ? +new Date(b.createdAt) - +new Date(a.createdAt) : String(a.name).localeCompare(String(b.name), "ru")), [sources, search, sort, filters]);
  const sourceStats = (s: Data) => reportSources.find(r => r.sourceId === s.id || r.id === s.id || r.code === s.code) ?? {};

  useEffect(() => {
    const chosen = linkScope ? sources.find(s => s.id === linkScope) : null;
    const raw = chosen?.links ?? chosen?.destinations ?? (linkScope ? {} : settings.links ?? settings.socialLinks ?? settings.destinations ?? {});
    setLinks({ vk: raw.vk ?? "", telegram: raw.telegram ?? "", max: raw.max ?? "" });
    setLinkModes(settings.linkModes ?? { vk: "plain", telegram: "plain", max: "plain" });
  }, [linkScope, data]);

  async function mutate(endpoint: string, body: Data, success: string, method = "POST") {
    setSaving(true); setNotice(null);
    try {
      const response = await fetch(`/api/admin/${endpoint}`, { method, headers: { "Content-Type": "application/json", "x-csrf-token": csrf }, body: JSON.stringify(body) });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) {
        const fieldNames: Record<string, string> = { code: "Код", printCode: "Печатный код", name: "Название", category: "Категория", platform: "Площадка", campaignId: "Кампания", cost: "Расходы", externalId: "Внешний ID", occurredAt: "Дата события", retentionDays: "Срок хранения", timezone: "Часовой пояс", categories: "Категории", platforms: "Площадки", type: "Тип события", sourceId: "Источник", count: "Количество" };
        const details = arr(result.issues).slice(0, 4).map(issue => `${(issue.path ?? []).map((key: string) => fieldNames[key] || LABELS[key] || key).join(" / ")}: ${issue.message}`).join("; ");
        throw new Error(`${result.error || `Ошибка сохранения (${response.status})`}${details ? `. ${details}` : ""}`);
      }
      const message = result.duplicate ? "Событие уже зарегистрировано. Повторная запись не создана." : endpoint === "import" ? `Импорт завершён. Добавлено: ${num(result.inserted)}. Повторов пропущено: ${num(result.duplicates)}.` : result.message || success;
      setNotice({ kind: "success", text: message }); setRefreshIndex(x => x + 1); return result;
    } catch (error) { setNotice({ kind: "error", text: error instanceof Error ? error.message : "Не удалось выполнить действие" }); return null; }
    finally { setSaving(false); }
  }
  function askDeletion(section: "campaigns" | "sources", form: Data) {
    const record = (section === "campaigns" ? campaigns : sources).find(item => item.id === form.id);
    if (!record) return;
    setDeleteConfirmation(""); setDeleteRequest({ section, record }); setCampaignForm(null); setSourceForm(null);
  }
  async function confirmDeletion() {
    if (!deleteRequest) return;
    const { section, record } = deleteRequest;
    const deletedIds = section === "campaigns" ? sources.filter(s => s.campaignId === record.id).map(s => s.id) : [record.id];
    const result = await mutate(section, { id: record.id, confirmation: deleteConfirmation }, "Удалено навсегда вместе со связанной статистикой.", "DELETE");
    if (!result) return;
    setDeleteRequest(null); setDeleteConfirmation(""); setSelected(ids => ids.filter(id => !deletedIds.includes(id)));
    setFilters(old => ({ ...old, campaignId: section === "campaigns" && old.campaignId === record.id ? "" : old.campaignId, sourceId: deletedIds.includes(old.sourceId) ? "" : old.sourceId }));
    if (deletedIds.includes(linkScope)) setLinkScope("");
    if (deletedIds.includes(conversion.sourceId)) setConversion(old => ({ ...old, sourceId: "" }));
    if (sourceDetail && deletedIds.includes(sourceDetail.id)) setSourceDetail(null);
  }
  function navigate(id: Section) { setCurrent(id); setMenu(false); window.history.replaceState(null, "", id === "dashboard" ? "/admin" : `/admin/${id}`); }
  function newSource() { const campaign = campaigns.find(c => c.id === filters.campaignId); setSourceForm({ ...structuredClone(EMPTY_SOURCE), campaignId: filters.campaignId || "", category: campaign ? (campaign.category || "") : EMPTY_SOURCE.category, isTest: filters.dataMode === "test" }); }
  async function logout() {
    try {
      const response = await fetch("/api/auth/logout", { method: "POST", headers: { "x-csrf-token": csrf } });
      if (!response.ok) { const result = await response.json(); throw new Error(result.error || "Не удалось выйти"); }
      window.location.href = "/admin/login";
    } catch (error) { setNotice({ kind: "error", text: error instanceof Error ? error.message : "Не удалось выйти" }); }
  }
  useEffect(() => { setSelected([]); }, [query]);
  const exportHref = (kind: string) => `/api/admin/export?kind=${kind}&${query}`;
  function rootUrl() { return String(settings.baseUrl ?? settings.siteUrl ?? (typeof window !== "undefined" ? window.location.origin : "" )).replace(/\/$/, ""); }
  function sourceUrls(s: Data) { const code = s.printCode || s.code; return { qr: s.urls?.main ?? `${rootUrl()}/r/${s.code}`, vk: s.urls?.vk ?? `${rootUrl()}/v/${code}`, telegram: s.urls?.telegram ?? `${rootUrl()}/t/${code}`, max: s.urls?.max ?? `${rootUrl()}/m/${code}` }; }
  async function copy(value: string) { try { await navigator.clipboard.writeText(value); setNotice({ kind: "success", text: "Ссылка скопирована" }); } catch { setNotice({ kind: "error", text: "Копирование недоступно. Выделите ссылку и скопируйте вручную." }); } }

  const table = (rows: Data[], mode: "sources" | "campaigns" = "sources") => <div className="adm-table-wrap"><table className="adm-table"><thead><tr><th>{mode === "sources" ? "Источник" : "Кампания"}</th><th>Входы</th><th>Посещения</th><th>Сессии</th><th>VK</th><th>Telegram</th><th>MAX</th><th>Конверсия</th><th>Расходы</th><th>Цена клика</th></tr></thead><tbody>{rows.map((r, i) => <tr key={r.sourceId ?? r.id ?? r.campaignId ?? i}><td><button className="adm-row-link" onClick={() => { if (mode === "sources") { const s = sources.find(s => s.id === (r.sourceId ?? r.id)); if (s) setSourceDetail(s); } else { setFilters({ ...filters, campaignId: r.campaignId ?? r.id }); navigate("sources"); } }}>{r.name ?? r.sourceName ?? r.campaignName ?? r.code ?? "Без источника"}</button>{r.code && <small>{r.code}</small>}</td><td>{num(getMetric(r, "incoming", "incomingClicks", "inbound"))}</td><td>{num(getMetric(r, "landingViews", "visits"))}</td><td>{num(getMetric(r, "uniqueSessions", "sessions"))}</td><td>{num(getMetric(r, "vk", "clicksVk") ?? r.clicks?.vk)}</td><td>{num(getMetric(r, "telegram", "clicksTelegram") ?? r.clicks?.telegram)}</td><td>{num(getMetric(r, "max", "clicksMax") ?? r.clicks?.max)}</td><td><span className="adm-rate">{percent(getMetric(r, "conversionRate", "conversion"))}</span></td><td>{money(r.cost ?? r.spend)}</td><td>{money(r.costPerClick ?? r.cpc)}</td></tr>)}</tbody></table>{!rows.length && <Empty/>}</div>;

  return <div className="adm-root">
    {menu && <button className="adm-nav-scrim" aria-label="Закрыть меню" onClick={() => setMenu(false)}/>}
    <aside className={`adm-sidebar${menu ? " adm-sidebar-open" : ""}`}><a className="adm-brand" href="/" aria-label="На сайт"><BrandLogo/><span className="adm-brand-tag">Управление проектом</span></a><div className="adm-workspace"><span className="adm-workspace-icon"><BrandLogo decorative/></span><span>Мой проект<small>Рекламная аналитика</small></span><span className="adm-dot"/></div><nav aria-label="Основная навигация">{NAV.map(item => <div key={item.id}>{item.group && <p className="adm-nav-group">{item.group}</p>}<button type="button" className={`adm-nav-item${current === item.id ? " active" : ""}`} onClick={() => navigate(item.id)}><Icon name={item.icon}/><span>{item.title}</span>{current === item.id && <span className="adm-nav-indicator"/>}</button></div>)}</nav><div className="adm-sidebar-bottom"><a href="/" target="_blank" rel="noreferrer"><Icon name="external" size={17}/>Открыть сайт</a><div className="adm-profile"><span className="adm-avatar">{user.email.slice(0, 1).toUpperCase()}</span><span>Администратор<small title={user.email}>{user.email}</small></span><button aria-label="Выйти" className="adm-icon-button" onClick={logout}><Icon name="logout" size={17}/></button></div></div></aside>
    <div className="adm-main"><header className="adm-topbar"><div><button className="adm-icon-button adm-mobile-toggle" onClick={() => setMenu(!menu)} aria-label="Открыть меню"><Icon name="menu"/></button><span className="adm-breadcrumb">Рабочее пространство <span>/</span> <strong>{activeNav.title}</strong></span></div><div className="adm-topbar-right"><button type="button" className="adm-icon-button adm-refresh-button" aria-label="Обновить данные" title={refreshBusy ? "Обновляем данные…" : "Обновить данные"} aria-busy={refreshBusy} disabled={refreshBusy} onClick={refreshData}><Icon name="refresh" size={22}/></button></div></header>
    <main className="adm-content"><div className="adm-page-heading"><div>{current !== "dashboard" && <div className="adm-eyebrow">IziWork / УПРАВЛЕНИЕ</div>}<h1>{activeNav.title}</h1>{current !== "dashboard" && <p>{({ dashboard: "", campaigns: "Объединяйте размещения, управляйте бюджетами и сравнивайте результат.", sources: "Постоянные рекламные адреса, QR-коды и статистика каждого размещения.", links: "Меняйте конечные адреса. Напечатанные ссылки и QR продолжат работать.", analytics: "Изучайте реальные события с учётом источника, периода и качества трафика.", content: "Редактируйте страницу без изменения кода. Публикация — отдельным действием.", conversions: "Только подтверждённые результаты, полученные вручную или через интеграции.", settings: "Домен, хранение данных, часовой пояс и необязательная аналитика.", audit: "История критических изменений и действий администраторов." } as Record<Section, string>)[current]}</p>}</div><div className="adm-heading-actions">{["dashboard", "analytics"].includes(current) && <a className="adm-button" href={exportHref("stats")}><Icon name="download" size={16}/>Экспорт CSV</a>}{current === "sources" && <button className="adm-button adm-button-primary" onClick={newSource}><Icon name="plus" size={18}/>Новый источник</button>}{current === "campaigns" && <button className="adm-button adm-button-primary" onClick={() => setCampaignForm({ name: "", category: "", budget: "", status: "active", comments: "" })}><Icon name="plus" size={18}/>Новая кампания</button>}</div></div>
    {notice && <div className={`adm-notice adm-notice-${notice.kind}`} role={notice.kind === "error" ? "alert" : "status"}><Icon name={notice.kind === "success" ? "check" : "file"} size={18}/><span>{notice.text}</span><button className="adm-icon-button" aria-label="Скрыть уведомление" onClick={() => setNotice(null)}><Icon name="close" size={15}/></button></div>}
    {loading && <div className="adm-loading" role="status"><span/>Обновляем данные…</div>}
    {["dashboard", "analytics", "sources", "campaigns", "conversions"].includes(current) && <section className="adm-filters" aria-label="Фильтры статистики"><div className="adm-periods">{[["today", "Сегодня"], ["yesterday", "Вчера"], ["7", "7 дней"], ["30", "30 дней"], ["custom", "Период"]].map(([id, title]) => <button key={id} className={period === id ? "active" : ""} onClick={() => setPeriod(id)}>{title}</button>)}</div><select aria-label="Кампания" value={filters.campaignId ?? ""} onChange={e => setFilters({ ...filters, campaignId: e.target.value })}><option value="">Все кампании</option>{campaigns.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select>{current === "conversions" && <select aria-label="Источник подтверждённых событий" value={filters.sourceId ?? ""} onChange={e => setFilters({ ...filters, sourceId: e.target.value })}><option value="">Все источники</option>{sources.map(s => <option key={s.id} value={s.id}>{s.name} · {s.code}</option>)}</select>}<select aria-label="Режим данных" value={filters.dataMode} onChange={e => setFilters({ ...filters, dataMode: e.target.value })}><option value="live">Рабочие данные</option><option value="test">Тестовые данные</option><option value="all">Все данные</option></select><select aria-label="Качество трафика" value={filters.quality} onChange={e => setFilters({ ...filters, quality: e.target.value })}><option value="clean">Очищенный трафик</option><option value="raw">Сырые события</option></select>{period === "custom" && <><input type="date" aria-label="Начало периода" value={filters.from ?? ""} onChange={e => setFilters({ ...filters, from: e.target.value })}/><span>—</span><input type="date" aria-label="Конец периода" value={filters.to ?? ""} onChange={e => setFilters({ ...filters, to: e.target.value })}/></>}{current === "analytics" && <div className="adm-advanced-filters"><select aria-label="Источник" value={filters.sourceId ?? ""} onChange={e => setFilters({ ...filters, sourceId: e.target.value })}><option value="">Все источники</option>{sources.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select><input placeholder="Площадка" aria-label="Площадка" value={filters.platform ?? ""} onChange={e => setFilters({ ...filters, platform: e.target.value })}/><input placeholder="Блогер / партнёр" aria-label="Блогер или партнёр" value={filters.partner ?? ""} onChange={e => setFilters({ ...filters, partner: e.target.value })}/><select aria-label="Тип трафика" value={filters.category ?? ""} onChange={e => setFilters({ ...filters, category: e.target.value })}><option value="">Все типы трафика</option>{[...new Set(["offline", "online", ...(settings.categories ?? []), ...sources.map(s => s.category)])].filter(Boolean).map(category => <option key={category} value={category}>{category === "offline" ? "Офлайн" : category === "online" ? "Онлайн" : category}</option>)}</select><input placeholder="Креатив" aria-label="Креатив" value={filters.creative ?? ""} onChange={e => setFilters({ ...filters, creative: e.target.value })}/><select aria-label="Устройство" value={filters.device ?? ""} onChange={e => setFilters({ ...filters, device: e.target.value })}><option value="">Все устройства</option><option value="mobile">Смартфон</option><option value="tablet">Планшет</option><option value="desktop">Компьютер</option><option value="unknown">Не определено</option></select><input value={filters.timezone ?? "Europe/Moscow"} aria-label="Часовой пояс" placeholder="Europe/Moscow" onChange={e => setFilters({ ...filters, timezone: e.target.value })}/><button className="adm-text-button" onClick={() => { setPeriod("30"); setFilters({ dataMode: "live", quality: "clean", timezone: "Europe/Moscow" }); }}>Сбросить фильтры</button></div>}</section>}

    {["dashboard", "sources", "campaigns", "conversions"].includes(current) && ["sourceId", "platform", "partner", "category", "creative", "device"].some(key => filters[key]) && <div className="adm-active-filters"><span>Активные фильтры:</span>{["sourceId", "platform", "partner", "category", "creative", "device"].filter(key => filters[key]).map(key => <button key={key} onClick={() => setFilters({ ...filters, [key]: "" })}>{({ sourceId: "Источник", platform: "Площадка", partner: "Партнёр", category: "Категория", creative: "Креатив", device: "Устройство" } as Record<string, string>)[key]}: {key === "sourceId" ? sources.find(s => s.id === filters[key])?.name ?? filters[key] : filters[key]}<Icon name="close" size={11}/></button>)}</div>}
    {["dashboard", "analytics"].includes(current) && <><div className="adm-stat-grid">{[
      { label: "Входящие переходы", value: num(getMetric(summary, "incoming", "incomingClicks", "inbound")), icon: "arrow", hint: "Все зарегистрированные входы" },
      { label: "Посещения сайта", value: num(visited), icon: "file", hint: "Загрузки посадочной страницы" },
      { label: "Уникальные сессии", value: num(sessions), icon: "layers", hint: "Оценка, сессия — 30 минут" },
      { label: "Конверсия в клик", value: percent(conversionRate), icon: "chart", hint: "Сессии с ≥ 1 кликом / сессии сайта", accent: true },
    ].map(item => <section className={`adm-stat${item.accent ? " adm-stat-accent" : ""}`} key={item.label}><div className="adm-stat-top"><span>{item.label}</span><Icon name={item.icon} size={18}/></div><strong>{item.value}</strong><small>{item.hint}</small></section>)}</div><div className="adm-quality-strip"><span>Сырые события <strong>{num(report.quality?.raw)}</strong></span><span>Очищенные <strong>{num(report.quality?.clean)}</strong></span><span>Исключено <strong>{num(report.quality?.excluded)}</strong></span><span className="adm-confirmed-total"><Icon name="check" size={14}/>Подтверждённые результаты <strong>{num(summary.confirmed ?? summary.confirmedConversions)}</strong></span></div><div className="adm-dashboard-middle"><Chart rows={daily}/><section className="adm-card adm-destinations"><div className="adm-card-heading"><div><h2>Выбор площадки</h2><p>Зарегистрированные переходы</p></div><Icon name="arrow" size={18}/></div>{["vk", "telegram", "max"].map((platform, i) => { const count = Number(getMetric(summary, platform, `clicks${platform === "vk" ? "Vk" : platform === "telegram" ? "Telegram" : "Max"}`) || summary.clicksByPlatform?.[platform] || summary.social?.[platform] || 0); return <div className="adm-platform" key={platform}><span className={`adm-platform-icon adm-platform-${platform}`}>{["VK", "↗", "M"][i]}</span><span>{PLATFORM_NAMES[platform]}<span className="adm-platform-progress"><i style={{ width: `${clicks ? Math.min(100, count / clicks * 100) : 0}%` }}/></span></span><strong>{num(count)}</strong></div>; })}<div className="adm-destination-total"><span>Всего кликов</span><strong>{num(clicks)}</strong></div><p className="adm-fineprint">Один человек может выбрать несколько площадок.</p></section></div><section className="adm-card"><div className="adm-card-heading"><div><h2>{current === "analytics" ? "Результаты источников" : "Источники трафика"}</h2><p>Сравнение размещений за выбранный период</p></div><button className="adm-text-button" onClick={() => navigate("sources")}>Все источники <Icon name="arrow" size={15}/></button></div>{table(current === "dashboard" ? reportSources.slice(0, 7) : reportSources)}</section>{current === "analytics" && <><section className="adm-card"><div className="adm-card-heading"><div><h2>Экономика размещений</h2><p>Показатели рассчитываются при наличии расходов и событий</p></div></div><div className="adm-economics-grid">{[["Расходы", money(summary.cost ?? summary.spend)], ["Цена посещения", money(summary.costPerVisit)], ["Цена сессии", money(summary.costPerSession)], ["Цена клика", money(summary.costPerClick)], ["Подтверждённые события", num(summary.confirmed ?? summary.confirmedConversions)], ["Цена подтверждённого лида", money(summary.costPerLead)]].map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div><p className="adm-panel-note">Цена подтверждённого лида — расходы, делённые только на число событий типа «Подтверждённый лид». ROI/ROMI без данных о доходе не рассчитывается.</p></section><section className="adm-card"><div className="adm-card-heading"><div><h2>Выгрузка отчётов</h2><p>Каждая выгрузка учитывает текущие фильтры</p></div></div><div className="adm-export-grid">{[["stats", "Общая статистика"], ["campaigns", "Кампании"], ["sources", "Источники"], ["events", "Переходы в соцсети"], ["links", "Рекламные ссылки и QR"]].map(([kind, label]) => <a key={kind} className="adm-button" href={exportHref(kind)}><Icon name="download" size={16}/>{label}</a>)}</div></section></>}</>}

    {current === "campaigns" && <><section className="adm-card"><div className="adm-card-heading"><div><h2>Рекламные кампании <span className="adm-count">{campaigns.length}</span></h2><p>Архивирование сохраняет источники и их постоянные адреса</p></div><a className="adm-text-button" href={exportHref("campaigns")}><Icon name="download" size={15}/>CSV</a></div>{campaigns.length ? <div className="adm-campaign-grid">{campaigns.map(c => { const stats = reportCampaigns.find(r => (r.campaignId ?? r.id) === c.id) ?? {}; return <article className="adm-campaign" key={c.id}><div className="adm-campaign-top"><span className="adm-campaign-icon"><Icon name="layers"/></span><span className={`adm-badge ${c.status === "archived" ? "adm-badge-muted" : ""}`}>{c.status === "archived" ? "В архиве" : "Активна"}</span></div><h3>{c.name}</h3><p>{CATEGORY_LABELS[c.category] || "Категория не выбрана"} · {sources.filter(s => s.campaignId === c.id).length} источников · {date(c.createdAt)}</p><div className="adm-campaign-metrics"><span>Бюджет<strong>{money(c.budget)}</strong></span><span>Посещения<strong>{num(getMetric(stats, "landingViews", "visits"))}</strong></span><span>Клики<strong>{num(getMetric(stats, "socialClicks", "clicks"))}</strong></span></div><div className="adm-campaign-actions"><button className="adm-button adm-button-small" onClick={() => { setFilters({ ...filters, campaignId: c.id }); navigate("sources"); }}>Источники<Icon name="arrow" size={15}/></button><button className="adm-text-button" onClick={() => setCampaignForm({ ...c })}>Изменить</button></div></article>; })}</div> : <Empty title="Соберите первую кампанию" text="Например, «Листовки · Санкт-Петербург» или «Посевы · Октябрь». Затем добавьте рекламные источники."><button className="adm-button adm-button-primary" onClick={() => setCampaignForm({ name: "", category: "", budget: "", status: "active", comments: "" })}>Создать кампанию</button></Empty>}</section>{reportCampaigns.length > 0 && <section className="adm-card"><div className="adm-card-heading"><h2>Сравнение кампаний</h2></div>{table(reportCampaigns, "campaigns")}</section>}</>}

    {current === "sources" && <section className="adm-card"><div className="adm-card-heading"><div><h2>Источники <span className="adm-count">{filteredSources.length}</span></h2><p>Открытие QR-ссылки учитывается как переход по URL</p></div><a className="adm-text-button" href={exportHref("links")}><Icon name="download" size={15}/>Таблица ссылок</a></div><div className="adm-table-toolbar"><div className="adm-search"><Icon name="search" size={17}/><input placeholder="Название, код, партнёр или город" aria-label="Поиск источников" value={search} onChange={e => setSearch(e.target.value)}/></div><select aria-label="Сортировка источников" value={sort} onChange={e => setSort(e.target.value)}><option value="name">По названию</option><option value="created">Сначала новые</option><option value="cost">По расходам</option></select>{selected.length > 0 && <a className="adm-button adm-button-small" href={`/api/admin/qr?ids=${selected.join(",")}&format=zip&size=${qrSize}`}><Icon name="download" size={15}/>QR выбранных ({selected.length})</a>}</div><div className="adm-table-wrap"><table className="adm-table"><thead><tr><th><input type="checkbox" aria-label="Выбрать до 100 источников" checked={filteredSources.length > 0 && selected.length === filteredSources.length} onChange={e => setSelected(e.target.checked ? filteredSources.slice(0, 100).map(s => s.id) : [])}/></th><th>Источник / код</th><th>Кампания</th><th>Тип / площадка</th><th>Посещения</th><th>VK / TG / MAX</th><th>Конверсия</th><th>Расходы</th><th>Статус</th><th/></tr></thead><tbody>{filteredSources.map(s => { const stats = sourceStats(s); return <tr key={s.id}><td><input type="checkbox" aria-label={`Выбрать ${s.name}`} disabled={!selected.includes(s.id) && selected.length >= 100} checked={selected.includes(s.id)} onChange={e => setSelected(e.target.checked ? [...selected, s.id] : selected.filter(id => id !== s.id))}/></td><td><button className="adm-row-link" onClick={() => setSourceDetail(s)}>{s.name}</button><small><code>{s.code}</code>{s.isTest && <span className="adm-test-tag">Тест</span>}</small></td><td>{campaigns.find(c => c.id === s.campaignId)?.name ?? "Без кампании"}</td><td>{CATEGORY_LABELS[s.category] || s.category || "Не выбрана"}<small>{s.platform}</small></td><td>{num(getMetric(stats, "landingViews", "visits"))}</td><td>{num(getMetric(stats, "vk", "clicksVk"))} / {num(getMetric(stats, "telegram", "clicksTelegram"))} / {num(getMetric(stats, "max", "clicksMax"))}</td><td><span className="adm-rate">{percent(getMetric(stats, "conversionRate", "conversion"))}</span></td><td>{money(s.cost)}</td><td><span className={`adm-badge ${s.active === false ? "adm-badge-muted" : ""}`}>{s.active === false ? "Неактивен" : "Активен"}</span></td><td><button className="adm-text-button" onClick={() => setSourceForm({ ...EMPTY_SOURCE, ...s, launchDate: s.launchDate ? String(s.launchDate).slice(0, 10) : "", links: s.links ?? EMPTY_SOURCE.links })}>Изменить</button></td></tr>; })}</tbody></table>{!filteredSources.length && <Empty title="Добавьте первое размещение" text="У каждого источника будут постоянная ссылка, QR-код и три коротких адреса для печати."><button className="adm-button adm-button-primary" onClick={newSource}>Создать источник</button></Empty>}</div></section>}

    {current === "links" && <><section className="adm-card"><div className="adm-card-heading"><div><h2>Конечные адреса</h2><p>Разрешены только HTTPS-адреса соответствующей социальной площадки</p></div></div><form className="adm-padded-form" onSubmit={async e => { e.preventDefault(); await mutate("links", { sourceId: linkScope || undefined, links, ...(!linkScope ? { linkModes } : {}) }, "Конечные адреса сохранены. Рекламные ссылки и QR не изменились."); }}><Field label="Область действия"><select value={linkScope} onChange={e => setLinkScope(e.target.value)}><option value="">Глобальные ссылки проекта</option>{sources.map(s => <option key={s.id} value={s.id}>{s.name} · {s.code}</option>)}</select></Field>{linkScope && <p className="adm-info">Пустое поле использует глобальную ссылку. Для источника можно указать индивидуальное приглашение или ссылку запуска бота.</p>}<div className="adm-form-grid">{["vk", "telegram", "max"].map(platform => <Field key={platform} label={PLATFORM_NAMES[platform]} wide hint={platform === "telegram" ? "Например, https://t.me/your_bot или персональная пригласительная ссылка." : platform === "max" ? "Укажите официальную HTTPS-ссылку канала, приглашения или бота MAX." : "HTTPS-ссылка сообщества, сообщения сообществу или бота."}><div className="adm-input-action"><input type="url" placeholder={platform === "vk" ? "https://vk.com/…" : platform === "telegram" ? "https://t.me/…" : "https://max.ru/…"} value={links[platform]} onChange={e => setLinks({ ...links, [platform]: e.target.value })}/>{links[platform] && <a className="adm-icon-button" href={links[platform]} target="_blank" rel="noreferrer" aria-label={`Проверить ${PLATFORM_NAMES[platform]}`}><Icon name="external" size={18}/></a>}</div></Field>)}</div>{!linkScope && <fieldset className="adm-content-group adm-link-mode-settings"><legend>Передача атрибуции в бота</legend><p className="adm-fineprint">Включайте только для совместимого бота. Каналы и обычные приглашения используйте без параметров. Получатель должен сам обработать значение.</p><div className="adm-form-grid">{["vk", "telegram", "max"].map(network => <Field label={PLATFORM_NAMES[network]} key={network}><select value={linkModes[network] ?? "plain"} onChange={e => setLinkModes({ ...linkModes, [network]: e.target.value })}><option value="plain">Без дополнительных параметров</option><option value="source">Передавать код источника</option><option value="click">Передавать уникальный ID клика</option></select></Field>)}</div></fieldset>}<button className="adm-button adm-button-primary" disabled={saving}>{saving ? "Сохранение…" : "Сохранить адреса"}</button></form></section><section className="adm-card"><div className="adm-card-heading"><div><h2>История изменений адресов</h2><p>Кто и когда изменил конечную ссылку</p></div></div><div className="adm-table-wrap"><table className="adm-table"><thead><tr><th>Дата</th><th>Администратор</th><th>Область</th><th>Площадка</th><th>Предыдущий адрес</th><th>Новый адрес</th></tr></thead><tbody>{history.map((h, i) => <tr key={h.id ?? i}><td>{date(h.createdAt, true)}</td><td>{h.actor || "—"}</td><td>{h.sourceId ? sources.find(s => s.id === h.sourceId)?.name ?? h.sourceId : "Глобально"}</td><td>{PLATFORM_NAMES[h.network ?? h.platform] ?? h.network ?? h.platform}</td><td className="adm-long-cell">{h.oldUrl ?? h.previousUrl ?? "—"}</td><td className="adm-long-cell">{h.newUrl ?? h.url ?? "—"}</td></tr>)}</tbody></table>{!history.length && <Empty title="История пока пуста" text="Изменения конечных адресов будут записаны автоматически."/>}</div></section></>}

    {current === "content" && <><section className="adm-card"><div className="adm-card-heading"><div><h2>Редактор посадочной страницы</h2><p>Тексты сохраняются как черновик до публикации</p></div><button className="adm-button adm-button-small" onClick={async () => { if (draft) { const result = await mutate("content", { draft }, "Черновик сохранён"); if (result) setPreview(true); } }}>Предпросмотр<Icon name="external" size={15}/></button></div>{draft ? <form className="adm-padded-form" onSubmit={async e => { e.preventDefault(); await mutate("content", { draft }, "Черновик сохранён. Опубликуйте его, когда всё будет готово."); }}><ContentEditor value={draft} onChange={setDraft}/><div className="adm-sticky-actions"><button className="adm-button" disabled={saving} type="submit">Сохранить черновик</button><button className="adm-button adm-button-primary" disabled={saving} type="button" onClick={() => mutate("content", { draft, publish: true }, "Изменения опубликованы на сайте")}>Опубликовать изменения<Icon name="arrow" size={16}/></button></div></form> : <Empty title="Загрузка содержимого" text="Проверьте соединение или обновите данные."/>}</section></>}

    {current === "conversions" && <><div className="adm-info">Эти события подтверждаются владельцем или внешней системой. Переход в соцсеть сам по себе не означает подписку, запуск бота или получение дохода.</div><section className="adm-card"><div className="adm-card-heading"><div><h2>Подтверждено за выбранный период</h2><p>Каждый тип результата учитывается отдельно</p></div></div><div className="adm-confirmed-grid">{Object.entries(CONFIRMED_LABELS).map(([type, label]) => <div key={type}><span>{label}</span><strong>{num(report.confirmedByType?.[type])}</strong></div>)}</div><p className="adm-panel-note">Цена подтверждённого лида: <strong>{money(summary.costPerLead)}</strong>. Расходы делятся только на число событий типа «Подтверждённый лид». Подписки, запуски бота и другие результаты в этот знаменатель не входят.</p></section><div className="adm-two-columns"><section className="adm-card"><div className="adm-card-heading"><div><h2>Добавить подтверждённый результат</h2><p>Ручная запись с привязкой к рекламному источнику</p></div></div><form className="adm-padded-form" onSubmit={async e => { e.preventDefault(); const result = await mutate("conversions", { ...conversion, count: Number(conversion.count), externalId: conversion.externalId || crypto.randomUUID(), occurredAt: conversion.occurredAt ? new Date(conversion.occurredAt).toISOString() : undefined }, "Подтверждённые результаты добавлены"); if (result) setConversion({ ...conversion, externalId: "", notes: "" }); }}><div className="adm-form-grid"><Field label="Рекламный источник" wide><select required value={conversion.sourceId} onChange={e => setConversion({ ...conversion, sourceId: e.target.value })}><option value="">Выберите источник</option>{sources.map(s => <option key={s.id} value={s.id}>{s.name} · {s.code}{s.isTest ? " (тест)" : ""}</option>)}</select></Field><Field label="Тип подтверждённого события"><select value={conversion.type} onChange={e => setConversion({ ...conversion, type: e.target.value })}><option value="lead">Подтверждённый лид</option><option value="subscribed">Подписка</option><option value="bot_started">Запуск бота</option><option value="task_started">Начало выполнения задач</option><option value="first_paid_task">Первая оплачиваемая задача</option></select></Field><Field label="Количество"><input type="number" min="1" max="100000" required value={conversion.count} onChange={e => setConversion({ ...conversion, count: Number(e.target.value) })}/></Field><Field label="Дата события" hint="Часовой пояс вашего устройства. Пустое поле — текущее время."><input type="datetime-local" value={conversion.occurredAt} onChange={e => setConversion({ ...conversion, occurredAt: e.target.value })}/></Field><Field label="Внешний ID" hint="Необязательно. Без значения система создаст уникальный идентификатор"><input value={conversion.externalId} onChange={e => setConversion({ ...conversion, externalId: e.target.value })}/></Field></div><button className="adm-button adm-button-primary" disabled={saving}>Добавить результат</button></form></section><section className="adm-card"><div className="adm-card-heading"><div><h2>Импорт из CSV</h2><p>Агрегированные подтверждённые результаты</p></div></div><form className="adm-padded-form" onSubmit={async e => { e.preventDefault(); await mutate("import", { csv }, "Импорт выполнен"); }}><Field label="Файл CSV" hint="UTF-8. Шаблон полей приведён ниже."><input type="file" accept=".csv,text/csv" onChange={async e => { const file = e.target.files?.[0]; if (file) setCsv(await file.text()); }}/></Field><Field label="Содержимое CSV"><textarea rows={8} value={csv} onChange={e => setCsv(e.target.value)} placeholder={'source_code,type,count,external_id,occurred_at\nspb01,lead,2,report-001,2026-10-24T12:00:00+03:00'}/></Field><button className="adm-button" disabled={saving || !csv.trim()}><Icon name="download" size={16}/>Импортировать</button></form></section></div><section className="adm-card"><div className="adm-card-heading"><div><h2>Зарегистрированные результаты <span className="adm-count">{confirmedResults.length}</span></h2><p>Последние 150 записей, соответствующих выбранным фильтрам</p></div></div><div className="adm-table-wrap adm-confirmed-table"><table className="adm-table"><thead><tr><th>Дата события</th><th>Источник</th><th>Подтверждённое событие</th><th>Количество</th><th>Способ записи</th><th>Внешний ID</th><th>Данные</th></tr></thead><tbody>{confirmedResults.map(result => <tr key={result.id}><td>{date(result.occurredAt, true)}</td><td>{result.sourceName || "Без названия"}<small><code>{result.sourceCode}</code></small></td><td>{CONFIRMED_LABELS[result.type] || result.type}</td><td>{num(result.count)}</td><td>{({ manual: "Вручную", import: "Импорт CSV", postback: "Postback / API", api: "Postback / API" } as Record<string, string>)[result.origin] || result.origin}</td><td className="adm-long-cell"><code>{result.externalId}</code></td><td>{result.isTest ? <span className="adm-test-tag">Тестовые</span> : <span className="adm-badge">Рабочие</span>}</td></tr>)}</tbody></table>{!confirmedResults.length && <Empty title="Подтверждённых результатов пока нет" text="Добавьте результат вручную, импортируйте CSV или измените период и режим данных."/>}</div></section><section className="adm-card"><div className="adm-card-heading"><div><h2>Серверные интеграции</h2><p>Telegram, MAX и CRM подключаются через защищённый postback</p></div></div><div className="adm-padded-form"><p className="adm-muted">Endpoint: <code>POST /api/postback</code>. Используйте серверный API-ключ и уникальный идентификатор события. Формат, проверка подписи и примеры запросов описаны в README проекта.</p><p className="adm-fineprint">Для автоматического подтверждения подписок необходимы соответствующие возможности платформы, права бота и совместимый идентификатор атрибуции.</p></div></section></>}

    {current === "settings" && <section className="adm-card"><div className="adm-card-heading"><div><h2>Настройки проекта</h2><p>Секреты интеграций хранятся на сервере, в переменных окружения</p></div></div>{settingsForm && <form className="adm-padded-form" onSubmit={async e => { e.preventDefault(); const result = await mutate("settings", { timezone: settingsForm.timezone, retentionDays: settingsForm.retentionDays, categories: (settingsForm.categories ?? []).map((s: string) => s.trim()).filter(Boolean), platforms: (settingsForm.platforms ?? []).map((s: string) => s.trim()).filter(Boolean), metrikaId: settingsForm.metrikaId }, "Настройки сохранены"); if (result) setFilters({ ...filters, timezone: settingsForm.timezone }); }}><div className="adm-form-grid"><Field label="Публичный адрес сайта" hint="Домен задаётся переменной APP_URL на сервере. Установите окончательный адрес до печати QR." wide><input type="url" readOnly value={sources[0]?.urls?.main ? new URL(sources[0].urls.main).origin : rootUrl()}/></Field><Field label="Часовой пояс отчётов"><input value={settingsForm.timezone ?? "Europe/Moscow"} placeholder="Europe/Moscow" onChange={e => setSettingsForm({ ...settingsForm, timezone: e.target.value })}/></Field><Field label="Срок хранения событий, дней" hint="После срока события удаляются служебной командой очистки"><input type="number" min="1" max="730" value={settingsForm.retentionDays ?? 90} onChange={e => setSettingsForm({ ...settingsForm, retentionDays: Number(e.target.value) })}/></Field><Field label="Номер счётчика Яндекс.Метрики" hint="Необязательно. Загружается только после согласия посетителя."><input inputMode="numeric" pattern="[0-9]*" value={settingsForm.metrikaId ?? ""} onChange={e => setSettingsForm({ ...settingsForm, metrikaId: e.target.value })}/></Field><Field label="Срок технической сессии"><input readOnly value="30 минут бездействия"/></Field><Field label="Категории источников" hint="По одной категории в строке. Например, offline и online."><textarea rows={4} value={(settingsForm.categories ?? ["offline", "online"]).join("\n")} onChange={e => setSettingsForm({ ...settingsForm, categories: e.target.value.split("\n") })}/></Field><Field label="Рекламные площадки" hint="По одной площадке в строке. Список можно расширять."><textarea rows={4} value={(settingsForm.platforms ?? []).join("\n")} onChange={e => setSettingsForm({ ...settingsForm, platforms: e.target.value.split("\n") })}/></Field></div><div className="adm-info">Не храните бессрочно полные IP-адреса. Перед запуском проверьте сведения об операторе, сроки хранения, правовые основания обработки и размещение данных.</div><button className="adm-button adm-button-primary" disabled={saving}>Сохранить настройки</button></form>}</section>}

    {current === "audit" && <section className="adm-card"><div className="adm-card-heading"><div><h2>Журнал административных действий</h2><p>Последние критические операции, записанные сервером</p></div></div><div className="adm-table-wrap"><table className="adm-table"><thead><tr><th>Дата и время</th><th>Администратор</th><th>Действие</th><th>Объект</th><th>Подробности</th></tr></thead><tbody>{audit.map((entry, i) => <tr key={entry.id ?? i}><td>{date(entry.createdAt, true)}</td><td>{entry.actor ?? entry.user?.email ?? entry.email ?? entry.adminEmail ?? "Система"}</td><td>{({ "auth.login": "Вход в управление", "auth.logout": "Выход из управления", "admin.create": "Создание администратора", "campaign.create": "Создание кампании", "campaign.update": "Изменение кампании", "source.create": "Создание источника", "source.update": "Изменение источника", "links.update": "Изменение ссылок", "content.draft": "Сохранение черновика", "content.publish": "Публикация сайта", "settings.update": "Изменение настроек", "conversion.create": "Подтверждение результата", "conversion.import": "Импорт результатов" } as Record<string, string>)[entry.action] ?? entry.action}</td><td>{entry.entity ?? entry.entityType ?? entry.target ?? sources.find(s => s.id === (entry.details?.id ?? entry.details?.sourceId))?.name ?? campaigns.find(c => c.id === entry.details?.id)?.name ?? "—"}{entry.entityId && <small>{entry.entityId}</small>}</td><td className="adm-long-cell">{typeof entry.details === "string" ? entry.details : entry.details ? JSON.stringify(entry.details) : "—"}</td></tr>)}</tbody></table>{!audit.length && <Empty title="Журнал пока пуст" text="Создание источников, изменения ссылок и публикации контента будут отображаться здесь."/>}</div></section>}
    <footer className="adm-footer"><span>IziWork · Собственная система трекинга</span><span>{filters.timezone || "Europe/Moscow"} <i>·</i> {filters.dataMode === "test" ? "Тестовые данные" : filters.dataMode === "all" ? "Все данные" : "Рабочие данные"}</span></footer>
    </main></div>

    {campaignForm && <Modal title={campaignForm.id ? "Редактирование кампании" : "Новая рекламная кампания"} close={() => setCampaignForm(null)}><form className="adm-modal-form" onSubmit={async e => { e.preventDefault(); const result = await mutate("campaigns", { ...campaignForm, budget: campaignForm.budget === "" ? null : Number(campaignForm.budget) }, "Кампания сохранена. Категория применена к её источникам."); if (result) setCampaignForm(null); }}><Field label="Название кампании"><input required maxLength={200} value={campaignForm.name} placeholder="Листовки · Санкт-Петербург" onChange={e => setCampaignForm({ ...campaignForm, name: e.target.value })}/></Field><Field label="Категория кампании" hint={campaignForm.id ? "При изменении категория обновится у всех источников этой кампании." : "Все источники кампании автоматически получат эту категорию."}><select required value={campaignForm.category ?? ""} onChange={e => setCampaignForm({ ...campaignForm, category: e.target.value })}><option value="" disabled>Выберите категорию</option><option value="offline">Офлайн</option><option value="online">Онлайн</option></select></Field><div className="adm-form-grid"><Field label="Бюджет, ₽"><input type="number" min="0" step="0.01" value={campaignForm.budget ?? ""} onChange={e => setCampaignForm({ ...campaignForm, budget: e.target.value })}/></Field><Field label="Статус"><select value={campaignForm.status ?? "active"} onChange={e => setCampaignForm({ ...campaignForm, status: e.target.value })}><option value="active">Активная</option><option value="archived">В архиве</option></select></Field></div><div className="adm-form-actions">{campaignForm.id && <button className="adm-button adm-button-danger adm-delete-action" type="button" disabled={saving} onClick={() => askDeletion("campaigns", campaignForm)}>Удалить кампанию</button>}<button className="adm-button" type="button" onClick={() => setCampaignForm(null)}>Отмена</button><button className="adm-button adm-button-primary" disabled={saving}>{saving ? "Сохранение…" : "Сохранить кампанию"}</button></div></form></Modal>}

    {sourceForm && <Modal title={sourceForm.id ? "Редактирование источника" : "Новый рекламный источник"} close={() => setSourceForm(null)} wide><form className="adm-modal-form" onSubmit={async e => { e.preventDefault(); const result = await mutate("sources", { ...sourceForm, printCode: sourceForm.printCode || sourceForm.code, campaignId: sourceForm.campaignId || null, cost: sourceForm.cost === "" ? 0 : Number(sourceForm.cost), launchDate: sourceForm.launchDate || "" }, "Источник сохранён. Ссылки и QR готовы к использованию."); if (result) { if (!sourceForm.id && result.id) setSourceDetail(result); setSourceForm(null); } }}><div className="adm-form-grid"><Field label="Название источника" wide><input required maxLength={200} value={sourceForm.name} placeholder="Расклейка · Приморский район" onChange={e => setSourceForm({ ...sourceForm, name: e.target.value })}/></Field><Field label="Постоянный код" hint={sourceForm.id ? "Код закреплён за источником и не меняется" : "Латиница, цифры, _ и -. Например, spb01"}><input required readOnly={Boolean(sourceForm.id)} pattern="[a-zA-Z0-9][a-zA-Z0-9_-]{1,31}" maxLength={32} value={sourceForm.code} placeholder="spb01" onChange={e => setSourceForm({ ...sourceForm, code: e.target.value })}/></Field><Field label="Короткий код для печати" hint="Необязательно. Например, p01. После создания остаётся постоянным."><input readOnly={Boolean(sourceForm.id)} pattern="[a-zA-Z0-9][a-zA-Z0-9_-]{1,31}|" maxLength={32} value={sourceForm.printCode ?? ""} placeholder="p01" onChange={e => setSourceForm({ ...sourceForm, printCode: e.target.value })}/></Field><Field label="Рекламная кампания"><select value={sourceForm.campaignId ?? ""} onChange={e => { const campaign = campaigns.find(c => c.id === e.target.value); setSourceForm({ ...sourceForm, campaignId: e.target.value, category: campaign ? (campaign.category || "") : sourceForm.category }); }}><option value="">Без кампании</option>{campaigns.map(c => <option key={c.id} value={c.id}>{c.name}{c.status === "archived" ? " (архив)" : ""}</option>)}</select></Field><Field label="Категория" hint={inheritedCategory ? "Наследуется из кампании. Изменить можно в разделе «Кампании»." : sourceCampaign ? "Категория кампании не выбрана. Задайте её в разделе «Кампании»." : undefined}>{sourceCampaign ? <input readOnly value={CATEGORY_LABELS[inheritedCategory] || inheritedCategory || ""} placeholder="Не выбрана"/> : <input list="adm-categories" required value={sourceForm.category} onChange={e => setSourceForm({ ...sourceForm, category: e.target.value })}/>}<datalist id="adm-categories">{[...new Set(["offline", "online", ...(settings.categories ?? []), ...sources.map(s => s.category)])].filter(Boolean).map(c => <option key={c} value={c}/>)}</datalist></Field><Field label="Площадка / тип размещения"><input list="adm-platforms" value={sourceForm.platform} onChange={e => setSourceForm({ ...sourceForm, platform: e.target.value })}/><datalist id="adm-platforms">{[...new Set(["VK", "Telegram", "Twitch", "YouTube", "Листовки", "Расклейка", "Почтовые ящики", ...(settings.platforms ?? []), ...sources.map(s => s.platform)])].map(p => <option key={p} value={p}/>)}</datalist></Field><Field label="Партнёр / блогер"><input value={sourceForm.partner ?? ""} onChange={e => setSourceForm({ ...sourceForm, partner: e.target.value })}/></Field><Field label="Город"><input value={sourceForm.city ?? ""} onChange={e => setSourceForm({ ...sourceForm, city: e.target.value })}/></Field><Field label="Район"><input value={sourceForm.district ?? ""} onChange={e => setSourceForm({ ...sourceForm, district: e.target.value })}/></Field><Field label="Место размещения"><input value={sourceForm.placement ?? ""} onChange={e => setSourceForm({ ...sourceForm, placement: e.target.value })}/></Field><Field label="Формат материала"><input value={sourceForm.material ?? ""} placeholder="Объявление A5" onChange={e => setSourceForm({ ...sourceForm, material: e.target.value })}/></Field><Field label="Название креатива"><input value={sourceForm.creative ?? ""} onChange={e => setSourceForm({ ...sourceForm, creative: e.target.value })}/></Field><Field label="Расходы, ₽"><input type="number" min="0" step="0.01" value={sourceForm.cost ?? ""} onChange={e => setSourceForm({ ...sourceForm, cost: e.target.value })}/></Field><Field label="Дата запуска"><input type="date" value={sourceForm.launchDate ?? ""} onChange={e => setSourceForm({ ...sourceForm, launchDate: e.target.value })}/></Field><div className="adm-field adm-check-stack"><label className="adm-check"><input type="checkbox" checked={sourceForm.active !== false} onChange={e => setSourceForm({ ...sourceForm, active: e.target.checked })}/>Активный источник</label><label className="adm-check"><input type="checkbox" disabled={Boolean(sourceForm.id)} checked={Boolean(sourceForm.isTest)} onChange={e => setSourceForm({ ...sourceForm, isTest: e.target.checked })}/>Тестовый источник</label></div><Field label="Комментарий" wide><textarea rows={3} value={sourceForm.comments ?? ""} onChange={e => setSourceForm({ ...sourceForm, comments: e.target.value })}/></Field></div><details className="adm-details"><summary>UTM-параметры</summary><div className="adm-form-grid">{["Source", "Medium", "Campaign", "Content", "Term"].map(key => <Field key={key} label={`utm_${key.toLowerCase()}`}><input value={sourceForm[`utm${key}`] ?? ""} maxLength={200} onChange={e => setSourceForm({ ...sourceForm, [`utm${key}`]: e.target.value })}/></Field>)}</div></details><details className="adm-details"><summary>Индивидуальные конечные ссылки</summary><p className="adm-fineprint">Пустые значения используют глобальные адреса проекта.</p>{["vk", "telegram", "max"].map(platform => <Field label={PLATFORM_NAMES[platform]} key={platform}><input type="url" value={sourceForm.links?.[platform] ?? ""} placeholder="https://…" onChange={e => setSourceForm({ ...sourceForm, links: { ...sourceForm.links, [platform]: e.target.value } })}/></Field>)}</details><div className="adm-form-actions">{sourceForm.id && <button className="adm-button adm-button-danger adm-delete-action" type="button" disabled={saving} onClick={() => askDeletion("sources", sourceForm)}>Удалить источник</button>}<button className="adm-button" type="button" onClick={() => setSourceForm(null)}>Отмена</button><button className="adm-button adm-button-primary" disabled={saving}>{saving ? "Сохранение…" : sourceForm.id ? "Сохранить изменения" : "Создать источник и QR"}</button></div></form></Modal>}

    {sourceDetail && <Modal title={sourceDetail.name} close={() => setSourceDetail(null)} wide><div className="adm-modal-form"><div className="adm-source-meta"><code>{sourceDetail.code}</code><span>Создан {date(sourceDetail.createdAt)}</span>{sourceDetail.isTest && <span className="adm-test-tag">Тестовый источник</span>}</div><div className="adm-source-detail-grid"><div className="adm-qr-preview"><img src={`/api/admin/qr?sourceId=${sourceDetail.id}&format=svg&size=512`} alt={`QR-код источника ${sourceDetail.name}`} width="210" height="210"/><span>Постоянный адрес вашего домена</span></div><div className="adm-source-links">{Object.entries(sourceUrls(sourceDetail)).map(([key, url]) => <div key={key}><label>{key === "qr" ? "Посадочная страница / QR" : `${PLATFORM_NAMES[key]} · прямая ссылка`}</label><div><input readOnly value={url} aria-label={`Ссылка ${key}`}/><button type="button" className="adm-icon-button" onClick={() => copy(url)} aria-label={`Скопировать ${key}`}><Icon name="copy" size={17}/></button><a className="adm-icon-button" href={url} target="_blank" rel="noreferrer" aria-label={`Открыть ${key}`}><Icon name="external" size={17}/></a></div></div>)}</div></div><div className="adm-qr-downloads"><select aria-label="Размер QR" value={qrSize} onChange={e => setQrSize(e.target.value)}>{[512, 1024, 2048, 4096].map(size => <option key={size} value={size}>{size} × {size} px</option>)}</select>{[["png", "PNG"], ["svg", "SVG"], ["a5", "Печать A5"], ["a6", "Печать A6"]].map(([format, label]) => <a key={format} className="adm-button adm-button-small" href={`/api/admin/qr?sourceId=${sourceDetail.id}&format=${format}&size=${qrSize}`}><Icon name="download" size={15}/>{label}</a>)}</div><p className="adm-fineprint">Логотип IziWork добавляется автоматически во всех форматах. В QR предусмотрено белое поле. Перед большим тиражом проверьте пробную распечатку камерой телефона. Переход по URL не равен подтверждённому сканированию.</p><div className="adm-detail-stats">{(() => { const r = sourceStats(sourceDetail); return [["Входящие переходы", num(getMetric(r, "incoming", "incomingClicks"))], ["Посещения", num(getMetric(r, "landingViews", "visits"))], ["Сессии (оценка)", num(getMetric(r, "uniqueSessions", "sessions"))], ["VK", num(getMetric(r, "vk", "clicksVk"))], ["Telegram", num(getMetric(r, "telegram", "clicksTelegram"))], ["MAX", num(getMetric(r, "max", "clicksMax"))], ["Конверсия", percent(getMetric(r, "conversionRate", "conversion"))], ["Расходы", money(sourceDetail.cost)], ["Цена посещения", money(r.costPerVisit)], ["Цена клика", money(r.costPerClick)], ["Подтверждённые события", num(r.confirmed ?? r.confirmedConversions)], ["Цена подтверждённого лида", money(r.costPerLead)]].map(([title, value]) => <div key={title}><span>{title}</span><strong>{value}</strong></div>); })()}</div><div className="adm-form-actions"><button className="adm-button" onClick={() => { setFilters({ ...filters, sourceId: sourceDetail.id }); setSourceDetail(null); navigate("analytics"); }}>Динамика и аналитика<Icon name="arrow" size={16}/></button><button className="adm-button adm-button-primary" onClick={() => { setSourceForm({ ...EMPTY_SOURCE, ...sourceDetail, launchDate: sourceDetail.launchDate ? String(sourceDetail.launchDate).slice(0, 10) : "" }); setSourceDetail(null); }}>Изменить источник</button></div></div></Modal>}
    {deleteRequest && <Modal title={deleteRequest.section === "campaigns" ? "Удалить кампанию навсегда?" : "Удалить источник навсегда?"} close={() => { if (!saving) setDeleteRequest(null); }}><form className="adm-modal-form" onSubmit={event => { event.preventDefault(); void confirmDeletion(); }}><p><strong>{deleteRequest.record.name}</strong></p><p className="adm-danger-note">{deleteRequest.section === "campaigns" ? ("Будут удалены кампания и все её источники (" + sources.filter(s => s.campaignId === deleteRequest.record.id).length + "), их переходы, сессии, подтверждённые события и история ссылок.") : "Будут удалены источник, его переходы, сессии, подтверждённые события и история ссылок."} Старые ссылки и QR перестанут работать. Восстановить через админку нельзя.</p>{deleteRequest.section === "sources" && deleteRequest.record.code === "offline_banners" && <p className="adm-danger-note">Также перестанут работать общие адреса /vk, /tg и /max.</p>}<Field label={deleteRequest.section === "campaigns" ? "Для подтверждения введите название кампании" : "Для подтверждения введите постоянный код источника"}><input autoFocus autoComplete="off" required value={deleteConfirmation} placeholder={deleteRequest.section === "campaigns" ? deleteRequest.record.name : deleteRequest.record.code} onChange={event => setDeleteConfirmation(event.target.value)}/></Field><p className="adm-fineprint">Данные удаляются из рабочей базы. Резервные копии очищаются по установленному сроку хранения.</p><div className="adm-form-actions"><button className="adm-button" type="button" disabled={saving} onClick={() => setDeleteRequest(null)}>Отмена</button><button className="adm-button adm-button-danger" disabled={saving || deleteConfirmation !== (deleteRequest.section === "campaigns" ? deleteRequest.record.name : deleteRequest.record.code)}>{saving ? "Удаление…" : "Удалить навсегда"}</button></div></form></Modal>}
    {preview && <Modal title="Предварительный просмотр черновика" close={() => setPreview(false)} wide><div className="adm-preview-toolbar"><span>Черновик виден только администратору</span><a href="/admin/preview" target="_blank" rel="noreferrer" className="adm-text-button">Открыть отдельно<Icon name="external" size={15}/></a></div><iframe title="Предварительный просмотр сайта" className="adm-preview-frame" src={`/admin/preview?updated=${refreshIndex}`}/></Modal>}
    </div>;
}
